exercises.solution:
function add(a, b) { return a + b; }
function assertEquals(expected, actual, label) {
  if (expected === actual) console.log("PASS " + label);
  else console.log("FAIL " + label);
}
assertEquals(4, add(2, 2), "adds positives");
assertEquals(0, add(-1, 1), "handles negatives");
